import test from 'node:test';import assert from 'node:assert/strict';
import {preparedPin,csvCell} from '../../assets/pinterest-plan-model.js';
const row={title:'Pinterest P01 · Fixture title',platforms:['pinterest'],kind:'social',scheduled:true,published:false,caption:'BOARD\nFixture board\n\nTITLE\nFixture title\n\nDESCRIPTION\nAn existing travel story.\n\nLINK\nhttps://dainyelonthemove.com/example?utm_source=pinterest#chapter\n\nTAGGED TOPICS (search and select available suggestions)\nTravel | Nature\n\nALT TEXT\nAn actual photograph.\n\nPrepared Pin and JPEG: owner archive'};
test('private Pin copy and manual scheduling state are parsed without changing the calendar',()=>{const p=preparedPin(row);assert.equal(p.pinId,'P01');assert.equal(p.pinTitle,'Fixture title');assert.equal(p.board,'Fixture board');assert.equal(p.description,'An existing travel story.');assert.equal(p.scheduled,true);assert.equal(p.published,false);assert.deepEqual(p.topics,['Travel','Nature']);assert.equal(p.alt,'An actual photograph.');assert.equal(row.title,'Pinterest P01 · Fixture title');});
test('unrelated tasks, malformed copy and external active links are not exposed as Pin metadata',()=>{assert.equal(preparedPin({...row,kind:'task'}),null);assert.equal(preparedPin({...row,caption:''}),null);assert.equal(preparedPin({...row,caption:row.caption.replace('https://dainyelonthemove.com/example','javascript:alert(1)')}),null);assert.equal(preparedPin({...row,platforms:['instagram']}),null);});
test('CSV copy export escapes quotes, newlines and spreadsheet formulas',()=>{assert.equal(csvCell('=1+1'),'"\'=1+1"');assert.equal(csvCell('a"b\nc'),'"a""b\nc"');});
